/// `yylex1`: the code of yacc for the token `t` of the lexer.
fn code(t: i32) -> i32 {
    match t {
        LTYPE0 => 14,
        LTYPE1 => 15,
        LTYPE2 => 16,
        LTYPE3 => 17,
        LTYPE4 => 18,
        LTYPEC => 19,
        LTYPED => 20,
        LTYPEN => 21,
        LTYPER => 22,
        LTYPET => 23,
        LTYPES => 24,
        LTYPEM => 25,
        LTYPEI => 26,
        LTYPEXC => 27,
        LTYPEX => 28,
        LTYPERT => 29,
        LCONST => 30,
        LFP => 31,
        LPC => 32,
        LSB => 33,
        LBREG => 34,
        LLREG => 35,
        LSREG => 36,
        LFREG => 37,
        LMREG => 38,
        LXREG => 39,
        LFCONST => 40,
        LSCONST => 41,
        LSP => 42,
        LNAME => 43,
        LLAB => 44,
        LVAR => 45,
        i32::MIN..=0 => 1,
        1..=126 => i32::from(TOK1[usize::try_from(t).unwrap_or(0)]),
        _ => 3,
    }
}

